 public static function contracts(array $p=[]): array {[$w,$a]=Auth::clientFilter('c.client_id',true);if(Auth::$user['role']==='staff')return [];if(!empty($p['client_id'])){$w.=' AND c.client_id=?';$a[]=(int)$p['client_id'];}$rows=DB::all('SELECT c.*,cl.name AS client_name FROM contracts c JOIN clients cl ON cl.id=c.client_id WHERE '.$w.' ORDER BY c.id DESC',$a);foreach($rows as &$c){$c['items']=DB::all('SELECT ci.*,ca.name AS category_name FROM contract_items ci JOIN categories ca ON ca.id=ci.category_id WHERE contract_id=?',[$c['id']]);$c['cycles']=self::cycles((int)$c['id']);}return $rows;}
 public static function cycles(int $contract): array {$rows=DB::all('SELECT * FROM cycles WHERE contract_id=? ORDER BY starts_on DESC LIMIT 36',[$contract]);foreach($rows as &$cy){$cy['items']=DB::all("SELECT ci.*,ca.name AS category_name,COALESCE((SELECT SUM(quantity) FROM demand_usage WHERE cycle_item_id=ci.id AND state='reserved'),0) AS reserved,COALESCE((SELECT SUM(quantity) FROM demand_usage WHERE cycle_item_id=ci.id AND state='consumed'),0) AS consumed FROM cycle_items ci JOIN categories ca ON ca.id=ci.category_id WHERE cycle_id=?",[$cy['id']]);foreach($cy['items'] as &$item)$item['available']=round((float)$item['quantity']+(float)$item['carried']-(float)$item['reserved']-(float)$item['consumed'],2);}return $rows;}
 public static function contractSave(array $p): array {Auth::admin();$id=(int)($p['id']??0);$old=$id?DB::one('SELECT * FROM contracts WHERE id=? FOR UPDATE',[$id]):null;if($id&&!$old)fail('Contrato não encontrado.',404);$client=integer($p['client_id'],1);Auth::client($client);if($old&&$old['client_id']!=$client)fail('O cliente do contrato não pode ser alterado.');$start=datev($p['starts_on'],false);$end=datev($p['ends_on']??null);if($end&&$end<$start)fail('Fim anterior ao início.');$row=['client_id'=>$client,'name'=>required($p,'name',190),'amount_cents'=>integer($p['amount_cents']??0),'starts_on'=>$start,'ends_on'=>$end,'interval_months'=>integer($p['interval_months']??1,1,12),'due_day'=>integer($p['due_day']??10,1,28),'status'=>enumv($p['status']??'active',['active','paused','cancelled'],'situação'),'carryover'=>(int)(bool)($p['carryover']??0),'revisions'=>integer($p['revisions']??2,0,1000),'auto_bill'=>(int)(bool)($p['auto_bill']??1),'terms'=>$p['terms']??''];if($old&&DB::one('SELECT id FROM cycles WHERE contract_id=?',[$id]))foreach(['starts_on','interval_months'] as $key)if((string)$row[$key]!== (string)$old[$key])fail('Contrato com ciclos: mantenha início e periodicidade; crie outro contrato para mudar a vigência.');if($id)DB::update('contracts',$id,$row);else $id=DB::insert('contracts',$row+['created_at'=>now()]);$items=$p['items']??[];if(!is_array($items)||!count($items)||count($items)>30)fail('Cadastre de 1 a 30 itens de franquia.');DB::run('DELETE FROM contract_items WHERE contract_id=?',[$id]);foreach($items as $item){$qty=(float)($item['quantity']??0);if($qty<=0||$qty>100000)fail('Quantidade da franquia inválida.');if(!DB::one('SELECT id FROM categories WHERE id=?',[$item['category_id']??0]))fail('Categoria inválida.');DB::insert('contract_items',['contract_id'=>$id,'category_id'=>(int)$item['category_id'],'unit'=>mb_substr($item['unit']??'unidade',0,30),'quantity'=>round($qty,2),'extra_cents'=>integer($item['extra_cents']??0)]);}audit('contract',$id,'save',$old,$row);self::ensureCycles($id);return ['id'=>$id];}
 private static function boundary(string $start,int $months): string {$d=new DateTimeImmutable($start);$first=$d->modify('first day of this month')->modify('+'.$months.' months');$day=min((int)$d->format('d'),(int)$first->format('t'));return $first->setDate((int)$first->format('Y'),(int)$first->format('m'),$day)->format('Y-m-d');}
 public static function ensureCycles(?int $id=null): int {$n=0;$today=(new DateTimeImmutable('now',new DateTimeZone(config('timezone'))))->format('Y-m-d');$contracts=DB::all("SELECT * FROM contracts WHERE status='active'".($id?' AND id=?':''),$id?[$id]:[]);foreach($contracts as $c){DB::one('SELECT id FROM contracts WHERE id=? FOR UPDATE',[$c['id']]);for($step=0;$step<1200;$step++){$start=self::boundary($c['starts_on'],$step*(int)$c['interval_months']);if($start>$today||($c['ends_on']&&$start>$c['ends_on']))break;$end=(new DateTimeImmutable(self::boundary($c['starts_on'],($step+1)*(int)$c['interval_months'])))->modify('-1 day')->format('Y-m-d');if($c['ends_on']&&$end>$c['ends_on'])$end=$c['ends_on'];if(DB::one('SELECT id FROM cycles WHERE contract_id=? AND starts_on=?',[$c['id'],$start]))continue;$cy=DB::insert('cycles',['contract_id'=>$c['id'],'starts_on'=>$start,'ends_on'=>$end,'amount_cents'=>$c['amount_cents']]);foreach(DB::all('SELECT * FROM contract_items WHERE contract_id=?',[$c['id']]) as $item){$carry=0;if($c['carryover']){$prev=DB::one('SELECT ci.* FROM cycle_items ci JOIN cycles cy ON cy.id=ci.cycle_id WHERE cy.contract_id=? AND cy.starts_on<? AND ci.category_id=? AND ci.unit=? ORDER BY cy.starts_on DESC LIMIT 1',[$c['id'],$start,$item['category_id'],$item['unit']]);if($prev){$used=DB::one("SELECT COALESCE(SUM(quantity),0) AS n FROM demand_usage WHERE cycle_item_id=? AND state IN ('reserved','consumed')",[$prev['id']]);$carry=max(0,(float)$prev['quantity']+(float)$prev['carried']-(float)$used['n']);}}DB::insert('cycle_items',['cycle_id'=>$cy,'category_id'=>$item['category_id'],'unit'=>$item['unit'],'quantity'=>$item['quantity'],'carried'=>$carry,'extra_cents'=>$item['extra_cents']]);}if($c['auto_bill']&&(int)$c['amount_cents']>0){$due=substr($start,0,8).str_pad((string)$c['due_day'],2,'0',STR_PAD_LEFT);if($due<$start)$due=(new DateTimeImmutable($due))->modify('+1 month')->format('Y-m-d');DB::insert('invoices',['client_id'=>$c['client_id'],'cycle_id'=>$cy,'description'=>$c['name'].' • '.$start,'amount_cents'=>$c['amount_cents'],'due_on'=>$due,'source_key'=>'cycle:'.$cy,'created_at'=>now()]);}$n++;}}return $n;}
