 public static function syncCommercialInvoices(?string $from=null,?string $to=null): int {
  $tz=new DateTimeZone(config('timezone','America/Fortaleza'));$now=new DateTimeImmutable('now',$tz);$explicit=$from!==null||$to!==null;
  $from=$from?:$now->modify('first day of this month')->format('Y-m-d');$to=$to?:$now->modify('last day of this month')->format('Y-m-d');
  $from=datev($from,false);$to=datev($to,false);if($from>$to)fail('Período financeiro inválido.');
  $start=(new DateTimeImmutable($from,$tz))->modify('first day of this month');$end=(new DateTimeImmutable($to,$tz))->modify('first day of this month');
  $months=0;$synced=0;$clients=DB::all("SELECT id,name,monthly_amount_cents,monthly_payment_day FROM clients WHERE active=1 AND commercial_type='monthly' AND monthly_amount_cents>0 ORDER BY id");
  for($cursor=$start;$cursor<=$end&&$months<120;$cursor=$cursor->modify('+1 month'),$months++){
   $ym=$cursor->format('Y-m');$days=(int)$cursor->format('t');
   foreach($clients as $client){$day=max(1,min($days,(int)($client['monthly_payment_day']??10)));$due=$ym.'-'.str_pad((string)$day,2,'0',STR_PAD_LEFT);$key='client-monthly:'.$client['id'].':'.$ym;$desc='Mensalidade • '.$client['name'].' • '.$cursor->format('m/Y');
    $invoice=DB::one('SELECT i.*,COALESCE((SELECT SUM(p.amount_cents) FROM payments p WHERE p.invoice_id=i.id),0) AS paid_cents FROM invoices i WHERE i.source_key=? LIMIT 1',[$key]);
    if(!$invoice){$legacy=DB::one("SELECT i.*,COALESCE((SELECT SUM(p.amount_cents) FROM payments p WHERE p.invoice_id=i.id),0) AS paid_cents FROM invoices i WHERE i.client_id=? AND i.status<>'cancelled' AND i.cycle_id IS NOT NULL AND DATE_FORMAT(i.due_on,'%Y-%m')=? AND i.amount_cents=? ORDER BY i.id LIMIT 1",[$client['id'],$ym,$client['monthly_amount_cents']]);if($legacy){$invoice=$legacy;}else{$id=DB::insert('invoices',['client_id'=>$client['id'],'description'=>$desc,'amount_cents'=>$client['monthly_amount_cents'],'due_on'=>$due,'source_key'=>$key,'created_at'=>now()]);$synced++;continue;}}
    if(($invoice['status']??'open')!=='cancelled'&&(int)($invoice['paid_cents']??0)===0&&empty($invoice['cycle_id'])){DB::update('invoices',(int)$invoice['id'],['description'=>$desc,'amount_cents'=>(int)$client['monthly_amount_cents'],'due_on'=>$due,'source_key'=>$key]);}
   }
  }
  $args=[];$where="d.deleted_at IS NULL AND d.billing_mode='one_off' AND d.amount_cents>0";if($explicit){$where.=' AND DATE(d.due_at) BETWEEN ? AND ?';$args=[$from,$to];}
  foreach(DB::all("SELECT d.id,d.client_id,d.project_id,d.title,d.amount_cents,d.due_at FROM demands d WHERE $where ORDER BY d.id",$args) as $d){$key='task:'.$d['id'];$invoice=DB::one("SELECT i.*,COALESCE((SELECT SUM(p.amount_cents) FROM payments p WHERE p.invoice_id=i.id),0) AS paid_cents FROM invoices i WHERE i.source_key=? OR (i.demand_id=? AND i.status<>'cancelled') ORDER BY (i.source_key=?) DESC,i.id LIMIT 1",[$key,$d['id'],$key]);$due=substr((string)$d['due_at'],0,10);if(!$invoice){DB::insert('invoices',['client_id'=>$d['client_id'],'demand_id'=>$d['id'],'project_id'=>$d['project_id'],'description'=>'Task #'.$d['id'].' • '.$d['title'],'amount_cents'=>$d['amount_cents'],'due_on'=>$due,'source_key'=>$key,'created_at'=>now()]);$synced++;continue;}if(($invoice['status']??'open')!=='cancelled'&&(int)($invoice['paid_cents']??0)===0){DB::update('invoices',(int)$invoice['id'],['description'=>'Task #'.$d['id'].' • '.$d['title'],'amount_cents'=>(int)$d['amount_cents'],'due_on'=>$due,'source_key'=>$key]);}}
  return $synced;
 }
 public static function monthlyClients(): array {Auth::admin();return DB::all("SELECT id,name,brand,monthly_amount_cents,monthly_payment_day,active FROM clients WHERE commercial_type='monthly' ORDER BY active DESC,name");}
 public static function monthlyBillingStatus(array $p=[]): array {
  Auth::admin();[$from,$to,$tz]=self::expenseRange($p);$month=(new DateTimeImmutable($from,$tz))->modify('first day of this month');$monthStart=$month->format('Y-m-d');$monthEnd=$month->modify('last day of this month')->format('Y-m-d');self::syncCommercialInvoices($monthStart,$monthEnd);$ym=$month->format('Y-m');$today=(new DateTimeImmutable('now',$tz))->format('Y-m-d');
  $clients=DB::all("SELECT id,name,brand,monthly_amount_cents,monthly_payment_day,active FROM clients WHERE active=1 AND commercial_type='monthly' AND monthly_amount_cents>0 ORDER BY name");
  $out=[];foreach($clients as $client){$key='client-monthly:'.$client['id'].':'.$ym;$invoice=DB::one("SELECT i.*,COALESCE((SELECT SUM(p.amount_cents) FROM payments p WHERE p.invoice_id=i.id),0) AS paid_cents FROM invoices i WHERE i.source_key=? ORDER BY i.id DESC LIMIT 1",[$key]);$billed=$invoice&&!$invoice['deleted_at']&&($invoice['status']??'open')!=='cancelled';$amount=(int)($invoice['amount_cents']??$client['monthly_amount_cents']);$paid=(int)($invoice['paid_cents']??0);$balance=$billed?max(0,$amount-$paid):$amount;$status='not_billed';if($billed)$status=$balance===0?'paid':($paid>0?'partial':(((string)$invoice['due_on']<$today)?'overdue':'pending'));$out[]=['client_id'=>(int)$client['id'],'client_name'=>$client['name'],'brand'=>$client['brand'],'monthly_amount_cents'=>(int)$client['monthly_amount_cents'],'payment_day'=>(int)$client['monthly_payment_day'],'month'=>$ym,'billed'=>(bool)$billed,'invoice_id'=>$billed?(int)$invoice['id']:null,'id'=>$billed?(int)$invoice['id']:null,'due_on'=>$invoice['due_on']??null,'amount_cents'=>$amount,'paid_cents'=>$paid,'balance_cents'=>$balance,'payment_status'=>$status,'deleted'=>(bool)($invoice['deleted_at']??false),'cancelled'=>(($invoice['status']??'')==='cancelled')];}
  return ['month'=>$ym,'from'=>$monthStart,'to'=>$monthEnd,'rows'=>$out,'billed'=>count(array_filter($out,fn($x)=>$x['billed'])),'not_billed'=>count(array_filter($out,fn($x)=>!$x['billed'])),'paid'=>count(array_filter($out,fn($x)=>$x['payment_status']==='paid')),'pending'=>count(array_filter($out,fn($x)=>in_array($x['payment_status'],['pending','partial','overdue'],true)))];
 }

 public static function invoices(array $p): array {
  if(Auth::$user['role']==='staff')fail('Financeiro restrito.',403);self::syncCommercialInvoices(!empty($p['from'])?(string)$p['from']:null,!empty($p['to'])?(string)$p['to']:null);[$w,$a]=Auth::clientFilter('i.client_id',true);$w.=' AND i.deleted_at IS NULL';
  if(!empty($p['client_id'])){$w.=' AND i.client_id=?';$a[]=(int)$p['client_id'];}
  if(!empty($p['from'])){$w.=' AND i.due_on>=?';$a[]=datev($p['from'],false);}
  if(!empty($p['to'])){$w.=' AND i.due_on<=?';$a[]=datev($p['to'],false);}
  if(!empty($p['q'])){$like='%'.trim((string)$p['q']).'%';$w.=' AND (i.description LIKE ? OR c.name LIKE ?)';array_push($a,$like,$like);}
  $rows=DB::all('SELECT i.*,c.name AS client_name,COALESCE((SELECT SUM(p.amount_cents) FROM payments p WHERE p.invoice_id=i.id),0) AS paid_cents FROM invoices i JOIN clients c ON c.id=i.client_id WHERE '.$w.' ORDER BY i.due_on,i.id',$a);
  $paymentsByInvoice=[];$ids=array_map(fn($i)=>(int)$i['id'],$rows);if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));foreach(DB::all('SELECT p.*,u.name AS created_by_name FROM payments p LEFT JOIN users u ON u.id=p.created_by WHERE p.invoice_id IN ('.$ph.') ORDER BY p.invoice_id,p.id',$ids) as $payment)$paymentsByInvoice[(int)$payment['invoice_id']][]=$payment;}
  foreach($rows as &$i){$i['balance_cents']=$i['status']==='cancelled'?0:max(0,(int)$i['amount_cents']-(int)$i['paid_cents']);$i['payment_status']=$i['status']==='cancelled'?'cancelled':($i['balance_cents']===0?'paid':($i['due_on']<gmdate('Y-m-d')?'overdue':((int)$i['paid_cents']>0?'partial':'pending')));$i['source_type']=str_starts_with((string)($i['source_key']??''),'client-monthly:')?'monthly':(str_starts_with((string)($i['source_key']??''),'task:')||$i['demand_id']?'task':'manual');$i['payments']=$paymentsByInvoice[(int)$i['id']]??[];}unset($i);
  if(!empty($p['status'])){$status=(string)$p['status'];$rows=array_values(array_filter($rows,fn($i)=>$status==='open'?($i['status']!=='cancelled'&&(int)$i['balance_cents']>0):$i['payment_status']===$status));}
  if(!empty($p['source'])){$source=(string)$p['source'];$rows=array_values(array_filter($rows,fn($i)=>$i['source_type']===$source));}
  if(!empty($p['paginate'])){$page=max(1,(int)($p['page']??1));$per=max(10,min(100,(int)($p['per_page']??30)));$total=count($rows);$rows=array_slice($rows,($page-1)*$per,$per);return ['rows'=>$rows,'pagination'=>['page'=>$page,'per_page'=>$per,'total'=>$total,'pages'=>max(1,(int)ceil($total/$per))]];}
  return $rows;
 }
 public static function log(array $p=[]): array {
  Auth::admin();$limit=max(1,min(200,(int)($p['limit']??100)));
  return DB::all("SELECT a.id,a.entity_id AS invoice_id,a.action,a.before_json,a.after_json,a.origin,a.created_at,u.name AS user_name,u.email AS user_email,i.description,i.amount_cents,i.due_on,i.deleted_at,i.delete_reason,c.name AS client_name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN invoices i ON i.id=a.entity_id LEFT JOIN clients c ON c.id=i.client_id WHERE a.entity='invoice' ORDER BY a.id DESC LIMIT ".$limit);
 }
 public static function invoiceCreate(array $p): array {Auth::admin();$client=integer($p['client_id'],1);Auth::client($client);$demand=!empty($p['demand_id'])?(int)$p['demand_id']:null;if($demand){$d=Auth::demand($demand);if($d['client_id']!=$client)fail('Demanda de outro cliente.');}$project=!empty($p['project_id'])?(int)$p['project_id']:null;if($project&&!DB::one('SELECT id FROM projects WHERE id=? AND client_id=?',[$project,$client]))fail('Projeto de outro cliente.');$description=required($p,'description',255);$amount=integer($p['amount_cents']??0,1);$due=datev($p['due_on']??'',false);if(empty($p['allow_duplicate'])){$dup=DB::one("SELECT id FROM invoices WHERE client_id=? AND description=? AND amount_cents=? AND due_on=? AND status<>'cancelled' AND deleted_at IS NULL LIMIT 1",[$client,$description,$amount,$due]);if($dup)fail('Já existe uma cobrança igual para este cliente e vencimento.',409,['duplicate_id'=>(int)$dup['id']]);}$id=DB::insert('invoices',['client_id'=>$client,'demand_id'=>$demand,'project_id'=>$project,'description'=>$description,'amount_cents'=>$amount,'due_on'=>$due,'created_at'=>now()]);audit('invoice',$id,'created',null,['client_id'=>$client,'description'=>$description,'amount_cents'=>$amount,'due_on'=>$due]);return ['id'=>$id];}
 public static function invoiceDemand(array $p): array {Auth::admin();$d=Auth::demand(integer($p['demand_id'],1),true);if($d['commercial_status']!=='approved')fail('Aprove o orçamento antes de cobrar.');$amount=(int)$d['amount_cents'];if($amount<=0||$d['billing_mode']!=='one_off')fail('Esta task não possui serviço avulso com valor para cobrança.');if(DB::one("SELECT id FROM invoices WHERE demand_id=? AND status<>'cancelled'",[$d['id']]))fail('Já existe cobrança para esta demanda.',409);$parts=integer($p['installments']??1,1,24);$date=datev($p['due_on']??'',false);$ids=[];$chunk=intdiv($amount,$parts);if($chunk===0)fail('Valor insuficiente para as parcelas.');for($i=0;$i<$parts;$i++){$ids[]=DB::insert('invoices',['client_id'=>$d['client_id'],'demand_id'=>$d['id'],'project_id'=>$d['project_id'],'description'=>$d['title'].' • parcela '.($i+1).'/'.$parts,'amount_cents'=>$chunk+($i===$parts-1?$amount-$chunk*$parts:0),'due_on'=>self::boundary($date,$i),'created_at'=>now()]);}audit('demand',$d['id'],'invoiced',null,['invoice_ids'=>$ids,'amount_cents'=>$amount]);return ['ids'=>$ids];}
 public static function payment(array $p): array {
  Auth::admin();
  return DB::tx(function() use($p): array {
   $i=DB::one('SELECT * FROM invoices WHERE id=? FOR UPDATE',[integer($p['invoice_id'],1)]);if(!$i||$i['status']==='cancelled'||!empty($i['deleted_at']))fail('Cobrança indisponível.');
   $amount=integer($p['amount_cents']??0,1);$paid=(int)(DB::one('SELECT COALESCE(SUM(amount_cents),0) AS n FROM payments WHERE invoice_id=?',[$i['id']])['n']??0);$refund=null;
   if(!empty($p['refund_of'])){
    $refund=DB::one('SELECT * FROM payments WHERE id=? AND invoice_id=?',[(int)$p['refund_of'],$i['id']]);if(!$refund||(int)$refund['amount_cents']<=0)fail('Pagamento original inválido.');
    $already=abs((int)(DB::one('SELECT COALESCE(SUM(amount_cents),0) AS n FROM payments WHERE refund_of=?',[$refund['id']])['n']??0));if($amount>(int)$refund['amount_cents']-$already)fail('Estorno acima do valor recebido.');$amount=-$amount;
   }elseif($amount>(int)$i['amount_cents']-$paid)fail('Pagamento maior que o saldo aberto.');
   $id=DB::insert('payments',['invoice_id'=>$i['id'],'amount_cents'=>$amount,'paid_on'=>datev($p['paid_on']??'',false),'method'=>required($p,'method',50),'note'=>mb_substr((string)($p['note']??''),0,1000),'refund_of'=>$refund['id']??null,'created_by'=>Auth::$user['id'],'created_at'=>now()]);
   audit('invoice',$i['id'],$refund?'refund':'payment',null,['payment_id'=>$id,'amount_cents'=>$amount,'method'=>$p['method']??'','paid_on'=>$p['paid_on']??'']);
   return ['id'=>$id];
  });
 }
 public static function cancel(array $p): array {Auth::admin();$i=DB::one('SELECT * FROM invoices WHERE id=? FOR UPDATE',[integer($p['id'],1)]);if(!$i)fail('Cobrança não encontrada.',404);$paid=(int)DB::one('SELECT COALESCE(SUM(amount_cents),0) AS n FROM payments WHERE invoice_id=?',[$i['id']])['n'];if($paid!==0)fail('Registre o estorno antes de cancelar a cobrança.');DB::update('invoices',$i['id'],['status'=>'cancelled']);audit('invoice',$i['id'],'cancelled');return ['saved'=>true];}
 public static function deleteInvoice(array $p): array {
